#!/bin/sh
# Regenerate docs/roadmap.md from milestone and child change proposals.
#
# Usage: roadmap.sh [--root <project dir>] [--today YYYY-MM-DD] [--stdout]
#
# A milestone is a change named m<NNN>-<slug>. Its goal is the text after
# "**Goal:**" in its proposal.md (fallback: first line under "## Why").
# A child is any change whose proposal.md contains a line "Milestone: m<NNN>".
#
# Safety: docs/roadmap.md is only replaced when it was generated by this
# script (frontmatter "generated_by: groma roadmap.sh"). Otherwise the output
# goes to docs/_groma/roadmap.md and the existing file is left untouched.
set -eu

HERE=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
# shellcheck source=SCRIPTDIR/lib-changes.sh
. "$HERE/lib-changes.sh"

ROOT=.
TODAY=$(date -u +%Y-%m-%d)
STDOUT=0
while [ $# -gt 0 ]; do
  case "$1" in
    --root) ROOT=$2; shift 2 ;;
    --today) TODAY=$2; shift 2 ;;
    --stdout) STDOUT=1; shift ;;
    *) echo "unknown argument: $1" >&2; exit 2 ;;
  esac
done

DIR=$(changes_dir "$ROOT")
LIST=$(list_changes "$DIR")
TAB=$(printf '\t')

upper_id() { echo "$1" | sed -nE 's/^([a-z]+[0-9]+)-.*/\1/p' | tr '[:lower:]' '[:upper:]'; }

goal_of() { # proposal path
  [ -f "$1" ] || { echo "-"; return; }
  g=$(sed -nE 's/^\*\*Goal:\*\*[ ]*//p' "$1" | head -n 1)
  [ -n "$g" ] || g=$(awk '/^## Why/ { f = 1; next } f && NF { print; exit }' "$1")
  echo "${g:--}"
}

render() {
  cat <<EOF
---
title: Roadmap
status: current
last_reviewed: $TODAY
review_after_days: 30
owner: groma
sources: [${DIR#"$ROOT"/}]
generated_by: groma roadmap.sh
---

# Roadmap

Generated from change proposals. Edit the milestone proposals, then run \`roadmap.sh\` again.
EOF
  milestones=$(printf '%s\n' "$LIST" | awk -F "$TAB" '$1 ~ /^m[0-9]+-/' | sort)
  if [ -z "$milestones" ]; then
    printf '\nNo milestones yet.\n'
  fi
  printf '%s\n' "$milestones" | while IFS="$TAB" read -r name loc path; do
    [ -n "$name" ] || continue
    mid=$(echo "$name" | sed -nE 's/^(m[0-9]+)-.*/\1/p')
    children=$(printf '%s\n' "$LIST" | while IFS="$TAB" read -r cn cl cp; do
      [ -f "$cp/proposal.md" ] || continue
      if grep -Eq "^Milestone:[ ]*${mid}([^0-9]|\$)" "$cp/proposal.md"; then printf '%s\t%s\n' "$cn" "$cl"; fi
    done | sort)
    total=0 done_n=0
    if [ -n "$children" ]; then
      total=$(printf '%s\n' "$children" | wc -l | tr -d ' ')
      done_n=$(printf '%s\n' "$children" | awk -F "$TAB" '$2 == "archive"' | wc -l | tr -d ' ')
    fi
    state="active"; [ "$loc" = archive ] && state="done"
    printf '\n## %s %s\n\n' "$(upper_id "$name")" "${name#*-}"
    printf -- '- Goal: %s\n- Status: %s\n- Progress: %s/%s done\n' "$(goal_of "$path/proposal.md")" "$state" "$done_n" "$total"
    if [ -n "$children" ]; then
      printf '\n| Id | Change | Status |\n|---|---|---|\n'
      printf '%s\n' "$children" | while IFS="$TAB" read -r cn cl; do
        st=$cl; [ "$cl" = archive ] && st="done"
        # shellcheck disable=SC2016
        printf '| %s | `%s` | %s |\n' "$(upper_id "$cn")" "$cn" "$st"
      done
    fi
  done
  unassigned=$(printf '%s\n' "$LIST" | while IFS="$TAB" read -r cn cl cp; do
    [ -n "$cn" ] || continue
    case "$cn" in (m[0-9]*-*) continue ;; esac
    [ "$cl" = active ] || continue
    if [ -f "$cp/proposal.md" ] && grep -Eq '^Milestone:[ ]*m[0-9]+' "$cp/proposal.md"; then continue; fi
    printf '%s\n' "$cn"
  done)
  if [ -n "$unassigned" ]; then
    printf '\n## Unassigned active changes\n\n'
    # shellcheck disable=SC2016
    printf '%s\n' "$unassigned" | while read -r cn; do printf -- '- `%s`\n' "$cn"; done
  fi
}

if [ "$STDOUT" -eq 1 ]; then
  render
  exit 0
fi

TARGET="$ROOT/docs/roadmap.md"
if [ -f "$TARGET" ] && ! grep -q '^generated_by: groma roadmap.sh' "$TARGET"; then
  mkdir -p "$ROOT/docs/_groma"
  TARGET="$ROOT/docs/_groma/roadmap.md"
  echo "docs/roadmap.md exists and was not generated by groma; writing $TARGET instead" >&2
fi
mkdir -p "$(dirname "$TARGET")"
render > "$TARGET"
echo "wrote $TARGET"
